export const pool = new SimplePool({ eoseTimeout: 8000 })

const RELAYS_VERSION = 2

export function getRelays() {
  try {
    const v = JSON.parse(localStorage.getItem('brasocial.relays'))
    if (Array.isArray(v) && v.length) {
      // migration: lists saved before the dead-relay curation are discarded
      if (v.some?.((r) => typeof r === 'string' && /aag\.eu\.org|wlvs\.space|nostr\.asia|bongbong|relayable\.org|fmt\.wiz\.biz|nostr\.band$/.test(r))) {
        localStorage.setItem('brasocial.relays', JSON.stringify(DEFAULT_RELAYS))
        return [...DEFAULT_RELAYS]
      }
      return v
    }
  } catch {}
  return [...DEFAULT_RELAYS]
}

export function setRelays(list) {
  localStorage.setItem('brasocial.relays', JSON.stringify(list))
}

export function getBlossomServers() {
  try {
    const v = JSON.parse(localStorage.getItem('brasocial.blossom'))
    if (Array.isArray(v) && v.length) return v
  } catch {}
  return [...DEFAULT_BLOSSOM]
}

export function setBlossomServers(list) {
  localStorage.setItem('brasocial.blossom', JSON.stringify(list))
}
