import React, { useEffect, useState } from 'react'
import { useApp } from './ctx'
import { DEFAULT_RELAYS, getRelays, setRelays, DEFAULT_BLOSSOM, getBlossomServers, setBlossomServers, pool } from '../lib/nostr'
import { resolveHost } from '../lib/dns'
import { clearTranslationCache } from '../lib/translate'
import { getNsec, } from '../lib/auth'
import { nip19 } from 'nostr-tools'
import { getRelays as relayListRef } from '../lib/nostr'

export function SettingsPage() {
  const { user, api, toast, nav, settings, setSetting } = useApp()
  if (!user) {
    return (
      <div className="settings card">
        <h2>Configurações</h2>
        <p className="muted">Você não está conectado.</p>
        <button className="btn primary" onClick={() => nav('/login')}>Conectar com nsec / criar chaves</button>
        <hr />
        <TranslateSection notify={toast} settings={settings} setSetting={setSetting} />
        <DnsSection notify={toast} />
      </div>
    )
  }
  return (
    <div className="settings card">
      <h2>Chaves e identidade</h2>
      <div className="small muted">
        pubkey: <code>{user.pubkey.slice(0, 16)}…{user.pubkey.slice(-8)}</code>
        <div>modo: {user.mode === 'nip07' ? 'extensão NIP-07' : 'chave local no navegador'}</div>
      </div>
      <div className="row gap wrap">
        {getNsec() && (
          <>
            <button className="btn ghost" onClick={() => { navigator.clipboard?.writeText(getNsec()); toast('ncertificados! nsec copiado — atenção: quem tem a nsec é o dono da conta') }}>Copiar nsec</button>
            <button className="btn ghost" onClick={() => navigator.clipboard?.writeText(nip19.npubEncode(user.pubkey)).then(() => toast('npub copiado'))}>Copiar npub</button>
          </>
        )}
        <button className="btn danger" onClick={() => { if (confirm('Desconectar? Sua chave local deixará de estar disponível!')) { api.logout(); toast('Desconectado'); nav('/') } }}>Sair / logout</button>
      </div>
      <hr />
      <RelaySection notify={toast} />
      <hr />
      <BlossomSection notify={toast} />
      <hr />
      <TranslateSection notify={toast} settings={settings} setSetting={setSetting} />
      <hr />
      <DnsSection notify={toast} />
    </div>
  )
}

function RelaySection({ notify }) {
  const [relays, setR] = useState(() => getRelays())
  const [status, setStatus] = useState({})
  const [newUrl, setNewUrl] = useState('')
  const check = (url) => {
    setStatus((s) => ({ ...s, [url]: 'conectando…' }))
    try {
      const t = setTimeout(() => setStatus((s) => ({ ...s, [url]: s[url] === 'conectando…' ? 'timeout' : s[url] })), 7000)
      pool.ensureRelay(url).then((relay) => {
        clearTimeout(t)
        const st = relay.status || 'ok'
        setStatus((s) => ({ ...s, [url]: st === 1 || st === 'ok' ? '✔ conectado' : String(st) }))
      }).catch((e) => { clearTimeout(t); setStatus((s) => ({ ...s, [url]: String(e).slice(0, 40) })) })
    } catch (e) { setStatus((s) => ({ ...s, [url]: String(e).slice(0, 40) })) }
  }
  const save = (list) => { setR(list); setRelays(list); notify('Lista de relays salva') }
  return (
    <div>
      <h3>Relays</h3>
      <p className="tiny muted">Os relays armazenam e propagam os eventos Nostr. Você pode adicionar os seus produtos.</p>
      {relays.map((r) => (
        <div key={r} className="relay-row">
          <code>{r}</code>
          <span className="flex1" />
          <button className="btn tiny ghost" onClick={() => check(r)}>{status[r] || 'testar'}</button>
          <button className="btn tiny ghost" onClick={() => save(relays.filter((x) => x !== r))}>×</button>
        </div>
      ))}
      <div className="row gap">
        <input value={newUrl} onChange={(e) => setNewUrl(e.target.value)} placeholder="wss://meu.relay.com" className="grow" />
        <button className="btn ghost" onClick={() => { if (newUrl.startsWith('wss://')) save([...relays, newUrl]); setNewUrl('') }}>+</button>
      </div>
      <button className="btn ghost" onClick={() => save([...DEFAULT_RELAYS])}>Restaurar padrão</button>
    </div>
  )
}

function BlossomSection({ notify }) {
  const [servers, setB] = useState(() => getBlossomServers())
  const [newUrl, setNewUrl] = useState('')
  const save = (list) => { setB(list); setBlossomServers(list); notify('Lista de servidores Blossom salva') }
  return (
    <div>
      <h3>Servidores Blossom (arquivos/imagens)</h3>
      <p className="tiny muted">Uploads vão para o primeiro servidor Blossom que responder (NIP-B). Nada fica na BraSocial.</p>
      {servers.map((s) => (
        <div key={s} className="relay-row">
          <code>{s}</code><span className="flex1" />
          <button className="btn tiny ghost" onClick={() => save(servers.filter((x) => x !== s))}>×</button>
        </div>
      ))}
      <div className="row gap">
        <input value={newUrl} onChange={(e) => setNewUrl(e.target.value)} placeholder="https://meu.blossom.com" />
        <button className="btn ghost" onClick={() => { if (newUrl.startsWith('https://')) save([...servers, newUrl]); setNewUrl('') }}>+</button>
      </div>
      <button className="btn ghost" onClick={() => save([...DEFAULT_BLOSSOM])}>Restaurar padrão</button>
    </div>
  )
}

function TranslateSection({ notify, settings, setSetting }) {
  return (
    <div>
      <h3>Tradução automática</h3>
      <label className="switch-row">
        <input
          type="checkbox" checked={!!settings.autoTranslate}
          onChange={(e) => setSetting('autoTranslate', e.target.checked)}
        />
        traduzir publicações para o idioma do navegador ({navigator.language})
      </label>
      <div className="row gap">
        <button
          className="btn ghost"
          onClick={() => {
            try { localStorage.removeItem('brasocial.translations') } catch {}
            notify('Cache de traduções limpo', 'info')
          }}
        >Limpar cache de tradução</button>
      </div>
    </div>
  )
}

export function DnsSection({ notify }) {
  const [host, setHost] = useState('relay.damus.io')
  const [result, setResult] = useState(null)
  const [busy, setBusy] = useState(false)
  const [relaysIps, setRelaysIps] = useState(null)
  const doResolve = async (h) => {
    setBusy(true)
    try {
      const r = await resolveHost(h || host, { fresh: true })
      setResult(r)
      if (r?.ips?.length) notify(`${h}: ${r.ips.join(', ')} — via ${r.resolver}`)
      else notify(`Não consegui resolver ${h}`, 'error')
    } catch (e) { notify(String(e), 'error') }
    setBusy(false)
  }
  const resolveAll = async () => {
    const list = getRelays()
    setRelaysIps([])
    for (const r of list.slice(0, 12)) {
      const hostOnly = r.replace(/^wss:\/\//, '').split('/')[0]
      try {
        const res = await resolveHost(hostOnly)
        setRelaysIps((arr) => [...(arr || []), { relay: hostOnly, ips: res?.ips || [] }])
      } catch { setRelaysIps((arr) => [...(arr || []), { relay: hostOnly, ips: [] }]) }
    }
  }
  return (
    <div>
      <h3>DNS no app (DoH)</h3>
      <p className="tiny muted">
        A BraSocial resolve nomes com <b>DNS-over-HTTPS (DoH)</b> dentro do app — consultas cifradas para servidores públicos
        independe da resolução do SO (relays/imagens continuam usando o domínio na conexão TLS, como a plataforma web exige).
      </p>
      <div className="row gap">
        <input className="grow" value={host} onChange={(e) => setHost(e.target.value)} placeholder="dominio.com.br" />
        <button className="btn primary" disabled={busy} onClick={() => doResolve()}>{busy ? 'resolvendo…' : 'Resolver'}</button>
        <button className="btn ghost" onClick={resolveAll}>Resolver relays</button>
      </div>
      {result && (
        <pre className="dns-result">{JSON.stringify({ ips: result.ips, ipv4: result.ipv4, ipv6: result.ipv6, via: result.resolver }, null, 2)}</pre>
      )}
      {relaysIps && (
        <div className="dns-list">
          {relaysIps.map((x) => (
            <div key={x.relay} className="relay-row">
              <code>{x.relay}</code><span className="flex1" /><span className="small">{x.ips.join(', ') || 'falhou'}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
