import {
  SimplePool, finalizeEvent, generateSecretKey, getPublicKey, nip19, verifyEvent,
} from 'nostr-tools'
import { pool, getRelays } from './nostr'

const USER_KEY = 'brasocial.user'

export { pool, getRelays, verifyEvent }

function bytesToHex(bytes) {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('')
}
function hexToBytes(hex) {
  if (hex.length % 2) return null
  const out = new Uint8Array(hex.length / 2)
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16)
  return out
}

// ---------- account state ----------
let current = null // { pubkey, secret: Uint8Array|null, mode: 'local'|'nip07' }

function loadStored() {
  try {
    const raw = JSON.parse(localStorage.getItem(USER_KEY))
    if (!raw?.pubkey) return null
    if (raw.nsec) {
      const data = nip19.decode(raw.nsec).data
      return { pubkey: raw.pubkey, secret: data, mode: 'local', nsec: raw.nsec }
    }
    return { pubkey: raw.pubkey, secret: null, mode: raw.mode || 'nip07' }
  } catch { return null }
}
current = loadStored()

export function getUser() { return current }

export async function loginWithNsec(nsecStr) {
  let decoded
  try { decoded = nip19.decode(nsecStr.trim()) } catch { throw new Error('nsec inválido') }
  if (decoded.type !== 'nsec') throw new Error('Cole um nsec (apenas chaves privadas começam com nsec1)')
  const secret = decoded.data
  const pubkey = getPublicKey(secret)
  current = { pubkey, secret, mode: 'local', nsec: nsecStr.trim() }
  localStorage.setItem(USER_KEY, JSON.stringify({ pubkey, nsec: current.nsec }))
  return current
}

export async function loginNip07() {
  if (!window?.nostr?.signEvent) throw new Error('Nenhuma extensão Nostr (NIP-07) detectada. Instale Alby ou nos2x.')
  const pubkey = await window.nostr.getPublicKey()
  current = { pubkey, secret: null, mode: 'nip07' }
  localStorage.setItem(USER_KEY, JSON.stringify({ pubkey, mode: 'nip07' }))
  return current
}

export function createNewKeys() {
  const secret = generateSecretKey()
  const nsec = nip19.nsecEncode(secret)
  const pubkey = getPublicKey(secret)
  current = { pubkey, secret, mode: 'local', nsec }
  localStorage.setItem(USER_KEY, JSON.stringify({ pubkey, nsec }))
  return current
}

export function switchToLocalKey(nsecStr) {
  // like loginWithNsec but keeps name for clarity; used when importing keys again
  return loginWithNsec(nsecStr)
}

export function logout() {
  current = null
  localStorage.removeItem(USER_KEY)
}

export function getNsec() { return current?.nsec || null }

// ---------- signing / publishing ----------
export async function signEvent(tpl, { user = current } = {}) {
  if (!user) throw new Error('Sem conta conectada')
  if (user.mode === 'nip07') {
    const ev = { ...tpl, pubkey: user.pubkey }
    return window.nostr.signEvent(ev)
  }
  const { created_at = Math.floor(Date.now() / 1000), tags = [], content = '' } = tpl
  const filterTags = tpl.kind === 10002 ? tpl.tags : tags
  return finalizeEvent({ kind: tpl.kind, created_at, tags: filterTags, content }, user.secret)
}

export async function publishEvent(ev, relaysOverride) {
  const relays = relaysOverride && relaysOverride.length ? relaysOverride : getRelays()
  const results = await Promise.allSettled(pool.publish(relays, ev))
  const ok = results.filter((r) => r.status === 'fulfilled').map((r) => r.value)
  const failed = results.filter((r) => r.status === 'rejected').map((r) => String(r.reason))
  if (!ok.length) console.warn('publicação falhou em todos os relays', failed, ev.kind)
  return { ok, failed }
}

// ---------- NIP-19 helpers ----------
export function npub(pk) { return nip19.npubEncode(pk) }
export function nevent(ev, relays = []) {
  return nip19.neventEncode({ id: ev.id, relays: relays.slice(0, 3), author: ev.pubkey, kind: ev.kind })
}
export function naddrOf(ev) {
  const d = ev.tags.find((t) => t[0] === 'd')?.[1] || ''
  return nip19.naddrEncode({ kind: ev.kind, pubkey: ev.pubkey, identifier: d, relays: getRelays().slice(0, 3) })
}
export function decodeNaddr(str) {
  try {
    const d = nip19.decode(str)
    if (d.type === 'naddr') return d.data
  } catch {}
  return null
}
export function communityA(ev) {
  const d = ev.tags.find((t) => t[0] === 'd')?.[1] || ''
  return `34550:${ev.pubkey}:${d}`
}

// ---------- reaction / repost tags ----------
export function noteE(relayMarker) {
  return relayMarker && relayMarker.startsWith('wss://') ? relayMarker : ''
}

export function sanitizeText(s) { return String(s ?? '').replace(/\u0000/g, '') }
