import React, { useEffect, useState } from 'react'
import { nip19 } from 'nostr-tools'
import { useApp } from './ctx'
import { Composer } from './Composer'
import { AuthorLine, Avatar, NoteBody, AutoTranslatedText, navReference } from './Thumb'
import { useStoreVersion } from '../lib/hooks'
import { hasLike, hasRepost, likesOf, repostsOf, childrenOf, getEvent, addEvent } from '../lib/store'
import { KINDS, mediaOf, communityOfEvent, urlsOf } from '../lib/nip22'
import { timeAgo, shortNpub, embedMediaUrl, embedVideoUrl } from '../lib/util'

export { AutoTranslatedText }

function icons() {}

function LikeIcon() {
  return <svg viewBox="0 0 24 24" width="17" height="17" fill="currentColor"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" /></svg>
}
function BubbleIcon() {
  return <svg viewBox="0 0 24 24" width="17" height="17" fill="currentColor"><path d="M20 2H4a2 2 0 0 0-2 2v18l4-4h14a2 2 0 0 0 2-2V4a2 2 0 0 0-2-2z" /></svg>
}
function RepostIcon() {
  return <svg viewBox="0 0 24 24" width="17" height="17" fill="currentColor"><path d="M7 7h10v3l4-4-4-4v3H5v6h2V7zm10 10H7v-3l-4 4 4 4v-3h12v-6h-2v4z" /></svg>
}
function QuoteIcon() {
  return <svg viewBox="0 0 24 24" width="17" height="17" fill="currentColor"><path d="M10 8v6a2 2 0 0 1-2 2H6v4l-2-2V4h8v4zm8 0v6a2 2 0 0 1-2 2h-2v4l-2-2V4h6v4z" /></svg>
}
function ShareIcon() {
  return <svg viewBox="0 0 24 24" width="17" height="17" fill="currentColor"><path d="M18 16.08c-.76 0-1.44.3-1.96.77L8.91 12.7c.05-.23.09-.46.09-.7s-.04-.47-.09-.7l7.05-4.11A2.99 2.99 0 0 0 21 5a3 3 0 1 0-9 0c0 .24.04.47.09.7L5.04 9.81A2.99 2.99 0 0 0 3 9c-1.66 0-3 1.34-3 3s1.34 3 3 3c1.3 0 2.4-.84 2.82-2h7.34c.14.63.47 1.18.94 1.59L18 16.08z" /></svg>
}
function TrashIcon() {
  return <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M6 19a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z" /></svg>
}

function CardBody({ ev }) {
  const auto = mediaOf(ev)
  const fromContent = urlsOf(ev.content || '').filter((u) => embedMediaUrl(u) || embedVideoUrl(u))
  const media = [...new Set([...auto, ...fromContent])]
  return (
    <div className="card-body">
      <NoteBody content={ev.content || ''} tags={ev.tags || []} media={media} />
    </div>
  )
}

function RepostCard({ event, depth = 0 }) {
  let inner = null
  try { inner = JSON.parse(event.content) } catch {}
  return (
    <article className={`post-card repost ${depth ? 'nested' : ''}`}>
      <div className="repost-line" onClick={(e) => e.stopPropagation()}>
        <RepostIcon /> repostado por <b>{shortNpub(event.pubkey, 12)}</b>
      </div>
      {inner ? <InnerPost ev={inner} depth={depth} /> : (
        <div className="repost-empty">repost (kind {event.kind}) sem conteúdo embutido</div>
      )}
    </article>
  )
}

function InnerPost({ ev, depth }) {
  const community = communityOfEvent(ev)
  return (
    <div className="repost-inner">
      <div className="post-head">
        <Avatar pk={ev.pubkey} size={30} />
        <AuthorLine pk={ev.pubkey} time={timeAgo(ev.created_at)} community={community} compact />
      </div>
      <CardBody ev={ev} />
    </div>
  )
}

export function PostCard({ event, context = 'feed', clickable = true }) {
  const { nav, user, api, toast } = useApp()
  useStoreVersion()
  const [replyOpen, setReplyOpen] = useState(false)
  const ev = event
  if (!ev) return null
  if (ev.kind === KINDS.REPOST || ev.kind === KINDS.GENERIC_REPOST) return <RepostCard event={ev} />
  const myPk = user?.pubkey
  const community = communityOfEvent(ev)
  const liked = myPk ? hasLike(ev.id, myPk) : false
  const reposted = myPk ? hasRepost(ev.id, myPk) : false
  const inlineReply = context === 'community'
  return (
    <article
      className="post-card"
      onClick={() => { if (clickable && context !== 'thread' && !replyOpen) nav(`/t/${ev.id}`) }}
      title={clickable && context !== 'thread' && !replyOpen ? 'Abrir thread' : ''}
    >
      <div className="post-head">
        <Avatar pk={ev.pubkey} size={38} onClick={() => nav(`/u/${nip19.npubEncode(ev.pubkey)}`)} />
        <AuthorLine
          pk={ev.pubkey} time={timeAgo(ev.created_at)}
          community={community && context !== 'community' ? community : null}
          onCommunityClick={() => nav(`/g/${community}`)}
        />
      </div>
      <CardBody ev={ev} />
      <div className="post-actions" onClick={(e) => e.stopPropagation()}>
        <button className="action" title={inlineReply ? 'Comentar aqui dentro' : 'Comentários'} onClick={() => {
          if (inlineReply) setReplyOpen((o) => !o)
          else nav(`/t/${ev.id}`)
        }}>
          <BubbleIcon /><span>{childrenOf(ev.id).size || ''}</span>
        </button>
        <button className={`action ${reposted ? 'on' : ''}`} title="Repostar"
          onClick={async () => {
            if (!myPk) return toast('Conecte uma conta para repostar', 'warn')
            try {
              if (reposted) return toast('Você já repostou isto', 'info')
              const kind = ev.kind === KINDS.POST ? KINDS.REPOST : KINDS.GENERIC_REPOST
              const t = await api.signEvent({ kind, tags: [['e', ev.id], ['p', ev.pubkey], ['k', String(ev.kind)]], content: JSON.stringify(ev) })
              await api.publishEvent(t)
              toast('Repostado!')
            } catch (e) { toast(String(e.message || e), 'error') }
          }}>
          <RepostIcon /><span>{repostsOf(ev.id) || ''}</span>
        </button>
        <button className={`action ${liked ? 'liked' : ''}`} title="Curtir"
          onClick={async () => {
            if (!myPk) return toast('Conecte uma conta para curtir', 'warn')
            if (liked) return toast('Você já curtiu isto', 'info')
            try {
              const tags = [['e', ev.id], ['p', ev.pubkey]]
              if (community) tags.push(['a', community])
              const t = await api.signEvent({ kind: KINDS.LIKE, tags, content: '+' })
              await api.publishEvent(t)
              toast('Curtido!')
            } catch (e) { toast(String(e.message || e), 'error') }
          }}>
          <LikeIcon /><span>{likesOf(ev.id) || ''}</span>
        </button>
        <button className="action" title="Citar no novo post" onClick={() => nav(`/compose?q=${ev.id}`)}>
          <QuoteIcon />
        </button>
        <button className="action" title="Copiar link"
          onClick={() => navigator.clipboard?.writeText(location.origin + location.pathname + `#/t/${ev.id}`).then(() => toast('Link copiado')).catch(() => toast('Não foi possível copiar', 'warn'))}>
          <ShareIcon />
        </button>
        {myPk === ev.pubkey && (
          <button className="action slim" title="Deletar (NIP-09)"
            onClick={async () => {
              if (!confirm('Publicar evento kind:5 para deletar esta publicação?')) return
              try {
                const t = await api.signEvent({ kind: KINDS.DELETE, tags: [['e', ev.id]], content: 'delete BraSocial' })
                await api.publishEvent(t)
                toast('Evento de deleção publicado (depende dos relays removê-lo)', 'warn')
              } catch (e) { toast(String(e.message || e), 'error') }
            }}>
            <TrashIcon />
          </button>
        )}
      </div>
      {replyOpen && (
        <div className="inline-reply" onClick={(e) => e.stopPropagation()}>
          <ComposerInline
            replyTo={{ ev, root: null, community }}
            onDone={(published) => { setReplyOpen(false); if (published) addEvent(published) }}
            onCancel={() => setReplyOpen(false)}
          />
        </div>
      )}
    </article>
  )
}

/** Inline comment composer (used inside community cards) */
function ComposerInline({ replyTo, onDone, onCancel }) {
  return (
    <div className="composer-card">
      <Composer replyTo={replyTo} onClose={(ev) => (ev ? onDone(ev) : onCancel())} />
    </div>
  )
}
