import React, { useState } from 'react'
import { useApp } from './ctx'
import { nip19 } from 'nostr-tools'

export function LoginModal({ onClose }) {
  const { api, toast, setUser, user, nav } = useApp()
  const [nsec, setNsec] = useState('')
  const [newKeys, setNewKeys] = useState(null)
  const [busy, setBusy] = useState(false)

  const doNsec = async () => {
    setBusy(true)
    try {
      const u = await api.loginWithNsec(nsec)
      setUser(u)
      toast('Conectado por nsec', 'ok')
      onClose?.()
    } catch (e) { toast(String(e.message || e), 'error') }
    setBusy(false)
  }
  const doNip07 = async () => {
    setBusy(true)
    try {
      const u = await api.loginNip07()
      setUser(u)
      toast('Conectado por extensão NIP-07', 'ok')
      onClose?.()
    } catch (e) { toast(String(e.message || e), 'error') }
    setBusy(false)
  }
  const generate = () => {
    const k = api.createNewKeys()
    setUser(k)
    setNewKeys(k)
    toast('Novo par de chaves criado', 'ok')
  }
  const shownNsec = newKeys?.nsec || (user?.mode === 'local' && user?.nsec)
  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal card" onClick={(e) => e.stopPropagation()}>
        <h3>Conectar na BraSocial</h3>
        {shownNsec ? (
          <div className="key-reveal card">
            <p className="tiny muted">Guarda! Esta é a sua chave privada (nsec). Anote. Quem a tiver controla a conta.</p>
            <div className="row">
              <code className="grow nsec-code">{shownNsec}</code>
              <button className="btn primary" onClick={() => { navigator.clipboard?.writeText(shownNsec); toast('nsec copiado') }}>Copiar</button>
            </div>
            <button className="btn primary full" onClick={onClose}>Já guardei, entrar</button>
          </div>
        ) : (
          <>
            <label className="field">Entre com sua nsec (NIP-06)
              <input
                type="password" value={nsec} onChange={(e) => setNsec(e.target.value)}
                placeholder="nsec1..." autoComplete="off"
              />
            </label>
            <div className="row gap">
              <button className="btn primary" disabled={busy} onClick={doNsec}>Entrar com nsec</button>
              <button className="btn secondary" disabled={busy} onClick={doNip07}>Extensão (NIP-07)</button>
            </div>
            <hr />
            <p className="tiny muted">Não tem chaves? Crie um par novo agora (você é o dono — a conta vive só das chaves).</p>
            <button className="btn primary full" disabled={busy} onClick={generate}>🔑 Criar novo par de chaves</button>
          </>
        )}
      </div>
    </div>
  )
}
