import { useEffect, useMemo, useState, useSyncExternalStore } from 'react'
import { pool, getRelays } from './nostr'
import { addEvent, subscribeStore, getEvent, replaceableLoc } from './store'
import { KINDS } from './nip22'

export function useStoreVersion() {
  return useSyncExternalStore(subscribeStore, (v) => v, () => 0)
}

function rels(r) { return r && r.length ? r : getRelays() }

/** nostr-tools 2.25 subscribeMany returns { close() } — older versions returned a function. */
function closeSub(sub) {
  const list = Array.isArray(sub) ? sub : sub ? [sub] : []
  list.forEach((u) => {
    try {
      if (typeof u === 'function') u()
      else if (u && typeof u.close === 'function') u.close('cleanup')
    } catch {}
  })
}

/**
 * Subscribe many relays with given filters. Events go into the global store.
 * Returns the ids that arrived (order-independent).
 */
export function useSub(filters, opts = {}) {
  const { relaysR = null, ceil = 1000, enabled = true } = opts
  const key = JSON.stringify(enabled ? filters : null)
  const [ids, setIds] = useState(() => [])
  const [didEose, setEose] = useState(false)
  useEffect(() => {
    if (!enabled || key === 'null') { setIds([]); return undefined }
    const known = new Set()
    let un = null, timer = null
    const flush = () => { timer = null; setIds([...known]) }
    const onev = (ev) => {
      if (!ev?.id || known.has(ev.id)) return
      known.add(ev.id)
      addEvent(ev)
      if (!timer) timer = setTimeout(flush, 150)
    }
    if (!filters.length) { setEose(true); return () => {} }
    try {
      // nostr-tools v2.25 SimplePool.subscribeMany takes ONE filter object per
      // call (multi-filter REQ wraps it nested and relays reject it).
      un = filters.map((f) => pool.subscribeMany(rels(relaysR), f, { onevent: onev, oneose: () => setEose(true) }))
      return () => { timer && clearTimeout(timer); closeSub(un) }
    } catch {
      setEose(true)
      return () => {}
    }
  }, [key, ceil, enabled])
  return { ids, eose: didEose }
}

const profileMem = new Map()
export function useProfile(pk) {
  const [p, setP] = useState(() => profileMem.get(pk) || null)
  useEffect(() => {
    if (!pk) return undefined
    setP(profileMem.get(pk) || null)
    if (profileMem.has(pk)) return undefined
    let dead = false
    pool.querySync(rels(getRelays().slice(0, 6)), { kinds: [KINDS.PROFILE], authors: [pk], limit: 1 })
      .then(([ev]) => {
        if (dead || !ev) return
        let meta = {}
        try { meta = JSON.parse(ev.content) } catch {}
        const prof = { ...meta, pubkey: pk, event: ev }
        profileMem.set(pk, prof)
        setP(prof)
      }).catch(() => {})
    return () => { dead = true }
  }, [pk])
  return p
}

export function lookupProfile(pk) { return profileMem.get(pk) || null }

const contactsMem = new Map()
export function useContacts(pk) {
  const [list, setList] = useState(() => contactsMem.get(pk) || null)
  useEffect(() => {
    if (!pk) return undefined
    setList(contactsMem.get(pk) || null)
    if (contactsMem.has(pk)) return undefined
    let dead = false
    pool.querySync(rels(getRelays().slice(0, 6)), { kinds: [KINDS.CONTACTS], authors: [pk], limit: 1 })
      .then(([ev]) => {
        if (dead || !ev) return
        const l = ev.tags.filter((t) => t[0] === 'p' && t[1]?.length === 64).map((t) => t[1])
        contactsMem.set(pk, l)
        setList(l)
      }).catch(() => {})
    return () => { dead = true }
  }, [pk])
  return list
}

export function getContacts(pk) { return contactsMem.get(pk) || null }

/** Latest replaceable event of kind for author + d, read from the store. */
export function useReplaceable(kind, pubkey, d = '') {
  useStoreVersion()
  const [fetched, setFetched] = useState(false)
  useEffect(() => {
    if (!pubkey || fetched) return undefined
    let dead = false
    pool.querySync(rels(getRelays().slice(0, 5)), { kinds: [kind], authors: [pubkey], ...(d ? { '#d': [d] } : {}), limit: 1 })
      .then((list) => { if (!dead) list.forEach(addEvent) })
      .catch(() => {})
      .finally(() => { if (!dead) setFetched(true) })
    return () => { dead = true }
  }, [kind, pubkey, d, fetched])
  return useMemo(() => replaceableLoc(kind, pubkey, d), [kind, pubkey, d, fetched])
}

/**
 * Full thread: fetches the root event and all nested kind-1111 comments,
 * growing the subscription as new replies arrive.
 */
export function useThread(rootId) {
  const [rootEv, setRootEv] = useState(() => (rootId ? getEvent(rootId) : null))
  const [comments, setComments] = useState(() => [])
  const [eose, setEose] = useState(false)
  useEffect(() => {
    setComments([])
    setEose(false)
    setRootEv(rootId ? getEvent(rootId) : null)
    const known = new Set([rootId].filter(Boolean))
    let un = null, flushT = null, growT = null
    const flush = () => { flushT = null; setComments(sortAsc([...known].filter((i) => i !== rootId).map(getEvent))) }
    const onev = (ev) => {
      if (!ev?.id || known.has(ev.id)) return
      known.add(ev.id)
      addEvent(ev)
      if (rootId && ev.id === rootId) setRootEv(ev)
      if (!flushT) flushT = setTimeout(flush, 150)
      if (growT) clearTimeout(growT)
      growT = setTimeout(() => { growT = null; start() }, 600)
    }
    const start = () => {
      if (un) { closeSub(un); un = null }
      const filters = []
      if (rootId) filters.push({ ids: [rootId] })
      const others = [...known].filter((k) => k !== rootId)
      if (others.length) filters.push({ '#e': others, kinds: [KINDS.COMMENT], limit: 800 })
      if (!filters.length) return
      try {
        // one filter per subscribeMany call (see note in useSub)
        un = filters.map((f) => pool.subscribeMany(rels(), f, { onevent: onev, oneose: () => setEose(true) }))
      } catch {}
    }
    start()
    return () => {
      closeSub(un)
      flushT && clearTimeout(flushT); growT && clearTimeout(growT)
    }
  }, [rootId])
  return { rootEvent: rootEv, comments, eose }
}

function sortAsc(evs) { return evs.filter(Boolean).sort((a, b) => a.created_at - b.created_at) }

export function useSortedEvents(ids, { asc = false } = {}) {
  useStoreVersion()
  const join = ids.join(',')
  return useMemo(() => {
    const evs = ids.map(getEvent).filter(Boolean)
    return evs.sort((a, b) => (asc ? a.created_at - b.created_at : b.created_at - a.created_at))
  }, [join, asc, useStoreVersion()])
}

/** IDs of a community (hashtag-like feed of its kind-1111 posts) */
export function useCommunityFeed(addr, enabled = true) {
  const { ids, eose } = useSub([{ '#a': [addr], kinds: [KINDS.COMMENT], limit: 600 }], { enabled })
  const ver = useStoreVersion()
  return useMemo(() => ({
    ids: ids.filter((id) => {
      const ev = getEvent(id)
      if (!ev) return false
      if (ev.kind === KINDS.POST) return true // legacy NIP-1 community post
      if (ev.kind === KINDS.COMMENT) return !ev.tags.some((t) => t[0] === 'e')
      return false
    }),
    eose,
  }), [ids.join(','), ver, enabled])
}

/** Communities joined by a user (NIP-72 pinned-groups list, kind 34555) with localStorage fallback */
export function useJoinedGroups(myPk) {
  useSub([{ kinds: [KINDS.PINNED_GROUPS], authors: myPk ? [myPk] : [] }], { enabled: !!myPk, ceil: 20 })
  useStoreVersion()
  const [tick, setTick] = useState(0)
  useEffect(() => {
    const onChange = () => setTick((t) => t + 1)
    window.addEventListener('storage', onChange)
    window.addEventListener('brasocial-joined-changed', onChange)
    return () => {
      window.removeEventListener('storage', onChange)
      window.removeEventListener('brasocial-joined-changed', onChange)
    }
  }, [])
  return useMemo(() => {
    if (!myPk) return []
    let local = []
    try { local = JSON.parse(localStorage.getItem('brasocial.joinedGroups') || '[]') } catch {}
    const ev = replaceableLoc(KINDS.PINNED_GROUPS, myPk, 'pinned-groups')
    const relay = ev ? ev.tags.filter((t) => t[0] === 'a' && t[1]?.startsWith('34550:')).map((t) => t[1]) : []
    const merged = new Set([...relay, ...local])
    return [...merged]
  }, [myPk, useStoreVersion(), tick])
}
