import React, { useMemo, useState } from 'react'
import { useApp } from './ctx'
import { PostCard } from './PostCard'
import { Composer } from './Composer'
import { Avatar, AuthorLine, LoadSpinner } from './Thumb'
import { useSub, useSortedEvents, useStoreVersion, useReplaceable } from '../lib/hooks'
import { replaceableLoc, addEvent } from '../lib/store'
import { KINDS } from '../lib/nip22'
import { uploadToBlossom } from '../lib/blossom'
import { dedupeRecent } from '../lib/util'

/* ---------------- list of groups ---------------- */
export function GroupsPage() {
  const { user, joined, nav, api, toast } = useApp()
  useStoreVersion()
  const { ids } = useSub([{ kinds: [KINDS.COMMUNITY_DEF], limit: 300 }], { ceil: 250 })
  const [creating, setCreating] = useState(false)
  const [q, setQ] = useState('')
  const evs = useSortedEvents(ids)
  const defs = useMemo(() => {
    const seen = new Map()
    for (const ev of evs) {
      const d = ev.tags.find((t) => t[0] === 'd')?.[1] || ''
      const key = `${ev.pubkey}:${d}`
      seen.set(key, ev)
    }
    const list = [...seen.values()]
    return list
      .map((ev) => {
        const name = ev.tags.find((t) => t[0] === 'name')?.[1] || ev.tags.find((t) => t[0] === 'd')?.[1] || 'c/(?'
        const desc = ev.tags.find((t) => t[0] === 'description')?.[1] || ''
        const img = ev.tags.find((t) => t[0] === 'image')?.[1] || null
        return { ev, name, desc, img, addr: `34550:${ev.pubkey}:${ev.tags.find((t) => t[0] === 'd')?.[1] || ''}` }
      })
      .filter((g) => !q || `${g.name} ${g.desc}`.toLowerCase().includes(q.toLowerCase()))
  }, [evs, q])
  return (
    <div className="groups-page">
      <div className="groups-head">
        <h2>Grupos</h2>
        <input className="search" placeholder="buscar grupo…" value={q} onChange={(e) => setQ(e.target.value)} />
        {user && <button className="btn primary" onClick={() => setCreating(true)}>+ Criar grupo</button>}
      </div>
      {joined.length > 0 && (
        <div className="joined-row">
          <span className="tiny muted">seus grupos:</span>
          {joined.map((a) => (
            <button key={a} className="chip" onClick={() => nav(`/g/${a}`)}>c/{addrName(a)}</button>
          ))}
        </div>
      )}
      <div className="groups-grid">
        {defs.map((g) => (
          <div key={g.ev.id} className="group-card card" onClick={() => nav(`/g/${g.addr}`)}>
            <div className="group-banner" style={g.img ? { backgroundImage: `url(${g.img})` } : {}}>
              {!g.img && 'c/…'}
            </div>
            <div className="group-info">
              <h4>c/{g.name}</h4>
              <p className="tiny muted">{g.desc?.slice(0, 140)}</p>
            </div>
          </div>
        ))}
        {defs.length === 0 && !q && <div className="muted empty"><LoadSpinner /> Carregando grupos existentes… ou crie o primeiro!</div>}
      </div>
      {creating && <CreateGroupModal onClose={() => setCreating(false)} />}
    </div>
  )
}

export function addrName(addr) {
  return addr.split(':')[2] || 'c/?'
}

/* ---------------- single group page ---------------- */
export function GroupPage({ pk, d }) {
  const { user, api, toast, nav, joined } = useApp()
  useStoreVersion()
  const def = useReplaceable(KINDS.COMMUNITY_DEF, pk, d)
  const addr = `34550:${pk}:${d}`
  const active = joined.includes(addr)
  const { ids } = useSub([
    { '#a': [addr], kinds: [KINDS.COMMENT], limit: 300 },
    { '#A': [addr], kinds: [KINDS.COMMENT], limit: 300 },
    { '#a': [addr], kinds: [KINDS.POST], limit: 200 },
  ], { ceil: 350 })
  const evs = useSortedEvents(ids)
  const [composerOpen, setComposerOpen] = useState(false)

  const name = def?.tags?.find((t) => t[0] === 'name')?.[1] || d || 'grupo'
  const description = def?.tags?.find((t) => t[0] === 'description')?.[1] || ''
  const image = def?.tags?.find((t) => t[0] === 'image')?.[1] || null
  const moderators = (def?.tags || []).filter((t) => t[0] === 'p' && (t[3] === 'moderator')).map((t) => t[1])

  return (
    <div className="group-page">
      <div className="group-hero card" style={image ? { backgroundImage: `url(${image})` } : {}}>
        <div className="hero-overlay">
          <button className="btn back" onClick={() => history.length > 1 ? history.back() : null}>← </button>
          <h2>c/{name}</h2>
          <p className="small">{description}</p>
          {user && (
<div className="row gap">
                <button
                  className={`btn ${active ? 'joined' : 'primary'}`}
                  onClick={() => toggleJoin(active, api, toast, addr, user.pubkey)}
                >
                  {active ? '✓ Participando' : '+ Participar'}
                </button>
                <button className="btn secondary" onClick={() => setComposerOpen((o) => !o)}>
                  + Postar no grupo
                </button>
              </div>
          )}
        </div>
      </div>
      {moderators.length > 0 && (
        <div className="tiny muted mods">moderadores: {moderators.map((m) => m.slice(0, 8)).join(', ')}</div>
      )}
      {composerOpen && (
        <div className="drawer"><Composer communityAddr={addr} onClose={() => setComposerOpen(false)} /></div>
      )}
      <GroupPostList evs={evs} />
    </div>
  )
}

const INITIAL = 30
const STEP = 15

function GroupPostList({ evs }) {
  const [n, setN] = useState(INITIAL)
  const uniq = useMemo(() => dedupeRecent(evs), [evs])
  const list = uniq.filter((ev) => ev.kind === KINDS.POST || (ev.kind === KINDS.COMMENT && !ev.tags.some((t) => t[0] === 'e')))
  const shown = list.slice(0, n)
  return (
    <>
      {shown.map((ev) => <PostCard key={ev.id} event={ev} context="community" />)}
      {evs.length === 0 && <p className="muted empty">Nenhum post neste grupo ainda. Publique o primeiro!</p>}
      {list.length > shown.length && (
        <div className="loadmore-row">
          <button className="btn ghost full" onClick={() => setN(n + STEP)}>
            Carregar mais {STEP} ({shown.length} de {list.length})
          </button>
        </div>
      )}
    </>
  )
}

function getFirstRelay() {
  try { return JSON.parse(localStorage.getItem('brasocial.relays'))?.[0] || 'wss://relay.primal.net' } catch { return 'wss://relay.primal.net' }
}

export async function toggleJoin(isJoined, api, toast, addr, myPk) {
  const ev = replaceableLoc(KINDS.PINNED_GROUPS, myPk, 'pinned-groups')
  const tags = []
  if (ev) {
    for (const t of ev.tags) {
      if (t[0] === 'a' && t[1] === addr) continue
      tags.push(t)
    }
  }
  if (!isJoined) tags.push(['a', addr], ['d', 'pinned-groups'])
  else tags.push(['d', 'pinned-groups'])
  try {
    const t = await api.signEvent({ kind: KINDS.PINNED_GROUPS, tags })
    await api.publishEvent(t)
    addEvent(t)
    // Also persist to localStorage for instant UI
    try {
      const local = JSON.parse(localStorage.getItem('brasocial.joinedGroups') || '[]')
      if (!isJoined && !local.includes(addr)) local.push(addr)
      else if (isJoined) local.splice(local.indexOf(addr), 1)
      localStorage.setItem('brasocial.joinedGroups', JSON.stringify(local))
      // Trigger real-time update across tabs/components
      window.dispatchEvent(new Event('brasocial-joined-changed'))
    } catch {}
    toast(isJoined ? 'Saiu do grupo' : 'Agora você participa do grupo', isJoined ? 'info' : 'ok')
  } catch (e) { toast(String(e), 'error') }
}

/* ---------------- create group ---------------- */
function CreateGroupModal({ onClose }) {
  const { user, api, toast, nav } = useApp()
  const [name, setName] = useState('')
  const [desc, setDesc] = useState('')
  const [slug, setSlug] = useState('')
  const [image, setImage] = useState(null)
  const [busy, setBusy] = useState(false)
  const fileRef = React.useRef(null)
  const identifier = (slug || slugify(name) || 'grupo-' + Math.random().toString(36).slice(2, 6))
  const uploadImg = async (f) => {
    try {
      const r = await uploadToBlossom(f)
      setImage(r.url)
      toast('Imagem do grupo enviada')
    } catch (e) { toast('Falha no upload: ' + (e.message || e), 'error') }
  }
  const create = async () => {
    if (!name.trim()) return toast('Dê um nome ao grupo', 'warn')
    setBusy(true)
    try {
      const tags = [
        ['d', identifier],
        ['name', name.trim()],
        ['description', desc.trim()],
        ['tag', 'brasocial'],
      ]
      if (image) tags.push(['image', image, '1200x400'])
      tags.push(['relay', getFirstRelay(), 'author'])
      tags.push(['relay', getFirstRelay(), 'requests'])
      tags.push(['relay', getFirstRelay(), 'approvals'])
      tags.push(['p', user.pubkey, getFirstRelay(), 'moderator'])
      const ev = await api.signEvent({ kind: KINDS.COMMUNITY_DEF, content: '', tags })
      const res = await api.publishEvent(ev)
      if (res.ok.length) {
        toast('Grupo criado!')
        addEvent(ev)
        nav(`/g/34550:${ev.pubkey}:${identifier}`)
        onClose?.()
      } else toast('Nenhum relay aceitou', 'error')
    } catch (e) { toast(String(e), 'error') }
    setBusy(false)
  }
  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal card" onClick={(e) => e.stopPropagation()}>
        <h3>Criar grupo</h3>
        <label className="field">Nome
          <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Nome do grupo" maxLength={60} />
        </label>
        <label className="field">Identificador (d-tag, não editável depois)
          <input value={identifier} onChange={(e) => setSlug(slugify(e.target.value))} placeholder="id-url-do-grupo" maxLength={40} />
        </label>
        <label className="field">Descrição
          <textarea value={desc} onChange={(e) => setDesc(e.target.value)} rows={3} maxLength={800} />
        </label>
        <div className="row">
          {image && <img src={image} alt="" style={{ width: 140, height: 70, objectFit: 'cover', borderRadius: 8 }} />}
          <input ref={fileRef} type="file" accept="image/*" hidden onChange={(e) => e.target.files[0] && uploadImg(e.target.files[0])} />
          <button className="btn ghost" onClick={() => fileRef.current?.click()}>🖼 Banner (Blossom)</button>
        </div>
        <div className="row end gap">
          <button className="btn ghost" onClick={onClose}>Cancelar</button>
          <button className="btn primary" disabled={busy} onClick={create}>{busy ? 'criando…' : 'Criar grupo'}</button>
        </div>
      </div>
    </div>
  )
}

function slugify(s) {
  return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9-]/g, '-').replace(/-+/g, '-').replace(/^-|-+$/g, '')
}
