import React, { useMemo, useState } from 'react'
import { nip19 } from 'nostr-tools'
import { useApp } from './ctx'
import { PostCard, AutoTranslatedText } from './PostCard'
import { Avatar, AuthorLine, LoadSpinner } from './Thumb'
import { useThread, useStoreVersion } from '../lib/hooks'
import { getEvent, likesOf, hasLike } from '../lib/store'
import { KINDS, parseRefs } from '../lib/nip22'
import { buildCommentTags } from '../lib/nip22'
import { timeAgo, shortNpub } from '../lib/util'

export function LikeIcon() {
  return <svg viewBox="0 0 24 24" width="15" height="15" fill="currentColor"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" /></svg>
}

/** parent event id = last `e` tag (our own comments always write parent last) */
function parentOf(c) {
  const es = c.tags.filter((t) => t[0] === 'e').map((t) => t[1])
  return es[es.length - 1] || null
}

export function ThreadPage({ id }) {
  const { nav, user, toast } = useApp()
  const { rootEvent, comments, eose } = useThread(id)
  useStoreVersion()

  const ctx = useMemo(() => {
    if (!rootEvent) return null
    const refs = parseRefs(rootEvent)
    return {
      community: refs.community,
      root: refs.community ? null : { id: rootEvent.id, kind: rootEvent.kind, pubkey: rootEvent.pubkey },
    }
  }, [rootEvent])

  const tops = useMemo(
    () => comments.filter((c) => parentOf(c) === id),
    [comments, id]
  )
  const groups = useMemo(() => {
    const m = new Map()
    for (const c of comments) {
      const p = parentOf(c)
      if (!p) continue
      if (!m.has(p)) m.set(p, [])
      m.get(p).push(c)
    }
    return m
  }, [comments])

  return (
    <div className="thread-page">
      <button className="btn back" onClick={() => history.length > 1 ? history.back() : nav('/')}>← Voltar</button>
      {!rootEvent && !eose && <div className="loading-row"><LoadSpinner /> buscando no relay…</div>}
      {rootEvent && <PostCard event={rootEvent} context="thread" clickable={false} />}
      {rootEvent && user && (
        <CommentReply target={rootEvent} community={ctx?.community} root={ctx?.root} onDone={null} />
      )}
      {tops.map((c) => (
        <CommentNode key={c.id} comment={c} groups={groups} root={ctx?.root} community={ctx?.community} depth={0} />
      ))}
      {!rootEvent && eose && (
        <p className="muted empty">Post não encontrado nos relays conectados. Pode ter sido deletado.</p>
      )}
    </div>
  )
}

function CommentNode({ comment, groups, root, community, depth }) {
  const { nav, user, api, toast } = useApp()
  useStoreVersion()
  const c = comment
  const [replyOpen, setReplyOpen] = useState(false)
  const [collapsed, setCollapsed] = useState(false)
  const myPk = user?.pubkey
  const liked = myPk ? hasLike(c.id, myPk) : false
  const children = groups.get(c.id) || []
  return (
    <div
      className="comment-node"
      style={{ marginLeft: depth ? 16 : 0, borderLeft: '2px solid var(--line)', paddingLeft: 12 }}
    >
      <div className="comment-head">
        <Avatar pk={c.pubkey} size={26} />
        <AuthorLine pk={c.pubkey} time={timeAgo(c.created_at)} compact />
        <span className="flex1" />
        {children.length > 0 && (
          <button className="tiny" onClick={() => setCollapsed((s) => !s)}>
            {collapsed ? `[+] ${children.length}` : '[-]'}
          </button>
        )}
      </div>
      {!collapsed && (
        <>
          <div className="comment-body"><AutoTranslatedText text={c.content || ''} /></div>
          <div className="comment-actions">
            <button className={`action ${liked ? 'liked' : ''}`} title="Curtir"
              onClick={async () => {
                if (!myPk) return toast('Conecte uma conta para curtir', 'warn')
                if (liked) return toast('Você já curtiu', 'info')
                try {
                  const t = await api.signEvent({ kind: KINDS.LIKE, tags: [['e', c.id], ['p', c.pubkey]], content: '+' })
                  await api.publishEvent(t)
                  toast('Curtido!')
                } catch (e) { toast(String(e.message || e), 'error') }
              }}>
              <LikeIcon /><span className="small">{likesOf(c.id) || ''}</span>
            </button>
            <button className="action" onClick={() => nav(`/t/${c.id}`)}>link</button>
            <button className="action" onClick={() => setReplyOpen((r) => !r)}>responder</button>
          </div>
          {replyOpen && (
            <CommentReply target={c} root={root} community={community} onDone={() => setReplyOpen(false)} />
          )}
          {!collapsed && children.map((child) => (
            <CommentNode key={child.id} comment={child} groups={groups} root={root} community={community} depth={depth + 1} />
          ))}
        </>
      )}
    </div>
  )
}

/** inline reply box; publishes a NIP-22 kind 1111 comment */
function CommentReply({ target, root, community, onDone }) {
  const { user, api, toast } = useApp()
  const [text, setText] = useState('')
  const [busy, setBusy] = useState(false)
  if (!user) return <p className="muted small">Conecte-se (nsec / extensão) para responder.</p>
  const submit = async () => {
    const content = text.trim()
    if (!content) return toast('Escreva um texto', 'warn')
    if (/nsec1[a-z0-9]{20,}/.test(content)) return toast('Nunca publique uma nsec!', 'error')
    setBusy(true)
    try {
      const tags = buildCommentTags({
        root,
        parent: target,
        community,
      })
      const ev = await api.signEvent({ kind: KINDS.COMMENT, content, tags })
      const res = await api.publishEvent(ev)
      toast(res.ok.length ? 'Comentário publicado' : 'Nenhum relay aceitou', res.ok.length ? 'ok' : 'error')
      if (res.ok.length) { setText(''); onDone?.() }
    } catch (e) { toast(String(e.message || e), 'error') }
    setBusy(false)
  }
  return (
    <div className="inline-reply">
      <textarea
        rows={2} className="composer-text flat" value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Escreva sua resposta…"
        onKeyDown={(e) => { if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') submit() }}
      />
      <div className="row end">
        {onDone && <button className="btn ghost" onClick={onDone}>Cancelar</button>}
        <button className="btn primary" disabled={busy} onClick={submit}>{busy ? 'enviando…' : 'Enviar'}</button>
      </div>
    </div>
  )
}
