// Simple in-app DNS resolver using DNS-over-HTTPS (DoH).
// The application resolves names itself over HTTPS instead of relying on the
// operating system's DNS servers (browser sandbox forbids raw UDP/TCP port 53,
// so DoH over 443 is the standard-compliant way to do it all client-side).

const WIRE_RESOLVERS = [
  'https://cloudflare-dns.com/dns-query',
  'https://dns.google/dns-query',
  'https://doh.mullvad.net/dns-query',
  'https://dns.quad9.net/dns-query',
]

const dnsCache = new Map() // `${name}|${type}` -> { expires, ips }

function randomTxId() {
  const arr = new Uint8Array(2)
  crypto.getRandomValues(arr)
  return (arr[0] << 8) | arr[1]
}

// Build a minimal DNS wire-format query (header + single question)
function buildQuery(name, typeA) {
  const out = []
  const push = (n) => out.push(n & 0xff)
  const tx = randomTxId()
  push(tx >> 8); push(tx & 0xff)
  push(0x01); push(0x00) // flags: standard query with recursion desired
  push(0x00); push(0x01) // QDCOUNT = 1
  push(0x00); push(0x00) // ANCOUNT
  push(0x00); push(0x00) // NSCOUNT
  push(0x00); push(0x00) // ARCOUNT
  for (const label of name.replace(/^\.+|\.+$/g, '').split('.')) {
    push(label.length)
    for (let i = 0; i < label.length; i++) push(label.charCodeAt(i))
  }
  push(0) // root label
  push(typeA ? 0x00 : 0x00); push(typeA ? 0x01 : 0x1c) // TYPE
  push(0x00); push(0x01) // CLASS IN
  return new Uint8Array(out)
}

function bytesToBase64url(bytes) {
  let bin = ''
  for (const b of bytes) bin += String.fromCharCode(b)
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

// Parse a DNS wire-format response, collecting A/AAAA/CNAME answer records
function parseResponse(buf) {
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength)
  const at = (i) => dv.getUint8(i)
  const qd = dv.getUint16(4), an = dv.getUint16(6)
  let i = 12
  // skip question section
  for (let q = 0; q < qd; q++) {
    while (i < buf.length) { const len = at(i); i++; if (len === 0) break; i += len }
    i += 4 // qtype + qclass
  }
  const ips = [], cnames = []
  const readName = (start) => {
    let p = start, labels = [], jumps = 0
    while (true) {
      const len = at(p)
      if (len === 0) return [labels.join('.'), p + 1]
      if (len & 0xc0) {
        const ptr = ((len & 0x3f) << 8) | at(p + 1)
        const [n] = readName(ptr)
        return [labels.length ? `${labels.join('.')}.${n}` : n, p + 2]
      }
      let s = ''
      for (let k = 0; k < len; k++) s += String.fromCharCode(at(p + 1 + k))
      labels.push(s)
      p += len + 1
      if (++jumps > 8) break
    }
    return [labels.join('.'), p]
  }
  for (let a = 0; a < an; a++) {
    const [, after] = readName(i)
    i = after
    if (i + 10 > buf.length) return { ips, cnames }
    const type = dv.getUint16(i)
    const rdlength = dv.getUint16(i + 8)
    i += 10
    if (type === 1 && rdlength === 4)
      ips.push([at(i), at(i + 1), at(i + 2), at(i + 3)].join('.'))
    else if (type === 28 && rdlength === 16) {
      const parts = []
      for (let x = 0; x < 8; x++) parts.push(dv.getUint16(i + x * 2).toString(16))
      ips.push(parts.join(':'))
    } else if (type === 5) {
      const [nm] = readName(i)
      if (nm) cnames.push(nm)
    }
    i += rdlength
  }
  return { ips, cnames }
}

const TYPE_A = true // 1 = A record, false = AAAA

async function queryWire(resolver, name, typeA) {
  let res
  try {
    res = await fetch(`${resolver}?dns=${bytesToBase64url(buildQuery(name, typeA))}`, {
      headers: { accept: 'application/dns-message' },
      signal: AbortSignal.timeout(5000),
    })
  } catch { return null }
  if (!res.ok) return null
  return parseResponse(new Uint8Array(await res.arrayBuffer()))
}

export async function resolveHost(name, { fresh = false } = {}) {
  name = String(name || '').trim().toLowerCase()
  if (!name) return null
  if (name.endsWith('.')) name = name.slice(0, -1)
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(name)) return { name, ips: [name], ipv4: [name], ipv6: [], resolver: 'literal' }
  const key = `${name}|all`
  const cached = dnsCache.get(key)
  if (cached && !fresh && cached.expires > Date.now()) return cached.value
  const shuffled = [...WIRE_RESOLVERS].sort(() => Math.random() - 0.5)
  let out = null
  for (const resolver of shuffled) {
    const [a, aaaa] = await Promise.all([
      queryWire(resolver, name, TYPE_A),
      queryWire(resolver, name, false),
    ])
    const ips = [...(a?.ips || []), ...(aaaa?.ips || [])]
    if (ips.length) {
      out = {
        name,
        ips,
        ipv4: a?.ips || [],
        ipv6: aaaa?.ips || [],
        cnames: { A: [], AAAA: [] },
        resolver: new URL(resolver).hostname,
      }
      out.cnames.A = a?.cnames || []
      out.cnames.AAAA = aaaa?.cnames || []
      break
    }
  }
  const value = out || { name, ips: [], ipv4: [], ipv6: [], error: 'NXDOMAIN/timeout', resolver: null }
  dnsCache.set(key, { expires: Date.now() + 5 * 60_000, value })
  return value
}

export function clearDnsCache() { dnsCache.clear() }
