import React, { useEffect, useMemo, useState } from 'react'
import { nip19 } from 'nostr-tools'
import { useApp } from './ctx'
import { useProfile } from '../lib/hooks'
import { displayName, hueFor, shortNpub, verifyNip05, embedMediaUrl, embedVideoUrl } from '../lib/util'
import { browserLang, cachedTranslation, translateText, isSameLang } from '../lib/translate'

export function Avatar({ pk, picture, size = 38, onClick }) {
  const prof = useProfile(pk)
  const img = picture || prof?.picture
  const [err, setErr] = useState(false)
  const hue = pk ? hueFor(pk) : 160
  if (img && !err) {
    return (
      <img
        src={img} alt="" className="avatar-img"
        style={{ width: size, height: size, borderRadius: '50%', objectFit: 'cover' }}
        onClick={onClick} onError={() => setErr(true)}
      />
    )
  }
  return (
    <div
      className="avatar-fallback" onClick={onClick}
      style={{ width: size, height: size, fontSize: size * 0.42, background: `linear-gradient(135deg, hsl(${hue} 72% 45%), hsl(${(hue + 60) % 360} 72% 32%))` }}
    >
      {(displayName(prof, pk)[0] || '?').toUpperCase()}
    </div>
  )
}

export function Nip05({ pk, nip05 }) {
  const [ok, setOk] = useState(false)
  useEffect(() => {
    let dead = false
    verifyNip05(nip05, pk).then((v) => { if (!dead) setOk(v) }).catch(() => {})
    return () => { dead = true }
  }, [nip05, pk])
  if (!nip05 || !ok) return null
  return <span className="nip05" title={`${nip05} verificado`}>{nip05}</span>
}

export function AuthorLine({ pk, time, community, compact = false, onCommunityClick }) {
  const prof = useProfile(pk)
  const { nav } = useApp()
  const meta = prof || {}
  return (
    <div className={`author-line ${compact ? 'compact' : ''}`}>
      <span
        className="author-name"
        onClick={(e) => { e.stopPropagation(); nav(`/u/${nip19.npubEncode(pk)}`) }}
      >{displayName(meta, pk)}</span>
      <Nip05 pk={pk} nip05={meta.nip05} />
      <span className="author-handle" onClick={(e) => { e.stopPropagation(); nav(`/u/${nip19.npubEncode(pk)}`) }}>
        @{(meta.name || shortNpub(pk, 10)).replace(/\s+/g, '_')}
      </span>
      {community && (
        <>
          <span className="dot">·</span>
          <span className="community-chip" onClick={(e) => { e.stopPropagation(); onCommunityClick?.() }}>
            c/:{community.split(':')[2]}
          </span>
        </>
      )}
      {time && <><span className="dot">·</span><span className="time-ago">{time}</span></>}
    </div>
  )
}

/** Text block that auto-translates to the browser language; keeps the original one clickable side by side */
function TranslatedContent({ content, renderOriginal }) {
  const { settings } = useApp()
  const target = browserLang()
  const [res, setRes] = useState(() => cachedTranslation(content, target))
  const [showOriginal, setShowOriginal] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(false)

  useEffect(() => {
    const cached = cachedTranslation(content, target)
    setRes(cached)
    setShowOriginal(false)
    setError(false)
    if (cached || !content?.trim() || content.length > 2500 || !settings.autoTranslate) return
    let dead = false
    setLoading(true)
    translateText(content)
      .then((r) => { if (!dead) { setRes(r); setError(false) } })
      .catch(() => { if (!dead) setError(true) })
      .finally(() => { if (!dead) setLoading(false) })
    return () => { dead = true }
  }, [content, target, settings.autoTranslate])

  const translated = settings.autoTranslate && res && res.text && !showOriginal && !isSameLang(res) && res.text !== content
  if (!content?.trim()) return renderOriginal() || null

  if (translated) {
    return (
      <React.Fragment>
        <span className="prewrap translated">{res.text}</span>
        <button className="mini-btn" onClick={() => setShowOriginal(true)}>ver original</button>
      </React.Fragment>
    )
  }

  return (
    <React.Fragment>
      {renderOriginal()}
      {(showOriginal || loading) && <button className="mini-btn" onClick={() => setShowOriginal(false)}>ver tradução</button>}
      {!showOriginal && !loading && !res && !error && settings.autoTranslate && content.length <= 2500 && (
        <button className="mini-btn" onClick={() => { setLoading(true); translateText(content).then((r) => { setRes(r); setLoading(false) }).catch(() => { setError(true); setLoading(false) }) }}>traduzir</button>
      )}
      {error && !loading && !res && (
        <button className="mini-btn" onClick={() => { setLoading(true); setError(false); translateText(content).then((r) => { setRes(r); setLoading(false) }).catch(() => { setError(true); setLoading(false) }) }}>tentar novamente</button>
      )}
    </React.Fragment>
  )
}

/** Renders note content: text, links, hashtags, images, videos and nostr: refs (single text block) */
export function NoteBody({ content, tags = [], media = [], className = '' }) {
  const { nav } = useApp()
  const parts = useMemo(() => {
    if (!content) return []
    const out = []
    const re = /https?:\/\/[^\s<>"')]+|(?:nostr:(?:nevent|note|naddr|npub|nprofile|nsec)1[a-z0-9]+)|#([\p{L}\p{N}_]+)/gu
    let last = 0, m
    while ((m = re.exec(content))) {
      if (m.index > last) out.push({ type: 'text', v: content.slice(last, m.index) })
      if (m[1]) out.push({ type: 'tag', v: m[1] })
      else if (/^(https?|nostr:)/.test(m[0])) out.push({ type: 'url', v: m[0] })
      last = m.index + m[0].length
    }
    if (last < content.length) out.push({ type: 'text', v: content.slice(last) })
    return out
  }, [content])

  const shown = new Set()
  const list = [
    ...media,
    ...tags.filter((t) => t[0] === 'imeta').map((t) => t[1]).filter(Boolean),
    ...parts.filter((p) => p.type === 'url' && (embedMediaUrl(p.v) || embedVideoUrl(p.v))).map((p) => p.v),
  ].filter((u) => { if (shown.has(u)) return false; shown.add(u); return true })
  const mediaSet = new Set(list)

  return (
    <div className={`note-body ${className}`}>
      <TranslatedContent
        content={content}
        renderOriginal={() => parts.map((p, i) => {
          if (p.type === 'text') return p.v.trim() ? <span key={i} className="prewrap">{p.v}</span> : null
          if (p.type === 'url') return mediaSet.has(p.v) ? null : <NoteLink key={i} url={p.v} />
          if (p.type === 'tag') return <a key={i} className="hashtag" onClick={() => nav(`/tag/${p.v}`)}>#{p.v}</a>
          return null
        })}
      />
      <div className="note-media">
        {list.map((u) => embedMediaUrl(u)
          ? <MediaImage key={u} url={u} />
          : <MediaVideo key={u} url={u} />)}
      </div>
    </div>
  )
}

/** <img> with error fallback chip (hosts that block hotlink / CORS) */
function MediaImage({ url }) {
  const [st, setSt] = useState('load') // load | ok | err
  return st === 'err' ? (
    <a className="media-fallback" href={url} target="_blank" rel="noreferrer noopener">
      🔗 imagem indisponível neste app — abrir em nova aba
    </a>
  ) : (
    <img
      src={url}
      alt=""
      loading="lazy"
      referrerPolicy="no-referrer"
      className={`note-img ${st === 'load' ? 'loading' : ''}`}
      onLoad={() => setSt('ok')}
      onError={() => setSt('err')}
    />
  )
}

/** <video> with typed <source> (servers that send octet-stream) + fallback */
function MediaVideo({ url }) {
  const [st, setSt] = useState('load')
  const srcDefault = /\.(mp4)$/i.test(url) ? 'video/mp4' : /\.(webm)$/i.test(url) ? 'video/webm' : /\.(mov)$/i.test(url) ? 'video/quicktime' : null
  return st === 'err' ? (
    <a className="media-fallback" href={url} target="_blank" rel="noreferrer noopener">
      🎬 vídeo indisponível neste player — abrir em nova aba
    </a>
  ) : (
    <video
      className="note-vid"
      controls
      preload="metadata"
      playsInline
      onError={() => setSt('err')}
    >
      {srcDefault && <source src={url} type={srcDefault} />}
      <source src={url} />
    </video>
  )
}

function NoteLink({ url }) {
  const { nav, toast } = useApp()
  if (url.startsWith('nostr:')) {
    const bech = url.slice(6)
    let data = null
    try { data = nip19.decode(bech) } catch { return <span className="link-broken">reference quebrada ({bech.slice(0, 12)}…)</span> }
    const label =
      data.type === 'nevent' || data.type === 'note' ? 'post' :
      data.type === 'naddr' ? 'grupo' :
      data.type === 'npub' ? 'perfil' : 'referência'
    return <a className="nostr-ref" onClick={() => navReference(bech, data, nav, toast)}>nostr:{label}</a>
  }
  return <a className="ext-link" href={url} target="_blank" rel="noreferrer noopener">{shortUrl(url)}</a>
}

export function navReference(bech, data, nav, toast) {
  if (data.type === 'nevent') nav(`/t/${data.data.id}`)
  else if (data.type === 'note') nav(`/t/${data.data}`)
  else if (data.type === 'naddr') nav(`/g/${data.data.kind}:${data.data.pubkey}:${data.data.identifier}`)
  else if (data.type === 'npub') nav(`/u/${bech}`)
  else toast('Não é possível navegar para esta referência', 'warn')
}

function shortUrl(u) {
  return u.replace(/^https?:\/\//, '').slice(0, 48) + (u.length > 48 ? '…' : '')
}

export function LoadSpinner() {
  return <div className="spinner"><div /></div>
}

/** Text block that auto-translates to the browser language; button reverts to original */
export function AutoTranslatedText({ text }) {
  return (
    <TranslatedContent
      content={text}
      renderOriginal={() => <span className="prewrap">{text}</span>}
    />
  )
}
