import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import {
  getUser, loginWithNsec, loginNip07, createNewKeys, logout, signEvent, publishEvent,
} from '../lib/auth'
import { useJoinedGroups } from '../lib/hooks'

const Ctx = createContext(null)
export function useApp() { return useContext(Ctx) }

function parseHash() {
  const h = (location.hash || '#/').replace(/^#/, '')
  const [path, q] = h.split('?')
  const parts = path.split('/').filter(Boolean)
  return { name: parts[0] || 'home', params: parts.slice(1), query: Object.fromEntries(new URLSearchParams(q || '')) }
}

export function CtxProvider({ children }) {
  const [route, setRoute] = useState(() => parseHash())
  const [user, setUser] = useState(() => getUser())
  const [settings, setSettings] = useState(() => {
    try { return JSON.parse(localStorage.getItem('brasocial.settings')) || {} } catch { return {} }
  })
  const [toast, setToastState] = useState(null)
  const joined = useJoinedGroups(user?.pubkey)

  useEffect(() => {
    const h = () => setRoute(parseHash())
    window.addEventListener('hashchange', h)
    return () => window.removeEventListener('hashchange', h)
  }, [])

  // Clicking a link to the CURRENT route refreshes it (remount with fresh data)
  const nav = useCallback((path) => {
    const target = path.startsWith('#') ? path : `#${path}`
    if (location.hash === target) setRoute((r) => ({ ...parseHash(), nonce: (r.nonce || 0) + 1 }))
    else location.hash = target
    window.scrollTo(0, 0)
  }, [])

  useEffect(() => {
    localStorage.setItem('brasocial.settings', JSON.stringify(settings))
  }, [settings])

  const showToast = useCallback((msg, kind = 'info') => {
    setToastState({ msg, kind })
    setTimeout(() => setToastState(null), 3200)
  }, [])

  // persist login switch (used by LoginModal)
  const value = useMemo(() => ({
    route, nav,
    user, setUser,
    joined,
    settings: { autoTranslate: true, ...settings },
    setSetting: (k, v) => setSettings((s) => ({ ...s, [k]: v })),
    toast: showToast,
    api: {
      loginWithNsec, loginNip07, createNewKeys, logout, signEvent, publishEvent,
    },
  }), [route, user, settings, joined])

  return (
    <Ctx.Provider value={value}>
      {children}
      {toast && <div className={`toast toast-${toast.kind}`} role="status">{toast.msg}</div>}
    </Ctx.Provider>
  )
}
