import React, { useEffect, useMemo, useRef, useState } from 'react'
import { nip04, nip19 } from 'nostr-tools'
import { useApp } from './ctx'
import { Avatar, LoadSpinner } from './Thumb'
import { useSub, useSortedEvents, lookupProfile } from '../lib/hooks'
import { getUser } from '../lib/auth'
import { displayName, shortNpub, timeAgo } from '../lib/util'

function nameOf(pk) {
  const n = displayName(lookupProfile(pk), pk)
  return n || shortNpub(pk, 8)
}

async function encryptFor(otherPk, text) {
  const u = getUser()
  if (u.mode === 'nip07') return window.nostr.nip04.encrypt(otherPk, text)
  return nip04.encrypt(u.secret, otherPk, text)
}

/** Decrypt a NIP-04 message for the local user. Returns { text } or { failed } when unreadable. */
function decryptText(ev, mePk) {
  try {
    const u = getUser()
    if (u.mode === 'nip07') {
      const from = ev.pubkey === mePk ? (ev.tags.find((t) => t[0] === 'p')?.[1] || mePk) : ev.pubkey
      return { text: window.nostr.nip04.decrypt(from, ev.content) }
    }
    if (u.secret) {
      if (ev.pubkey === mePk) {
        const to = ev.tags.find((t) => t[0] === 'p')?.[1] || mePk
        return { text: nip04.decrypt(u.secret, to, ev.content) }
      }
      return { text: nip04.decrypt(u.secret, ev.pubkey, ev.content) }
    }
  } catch {}
  return { failed: true }
}

/* ---------------- inbox ---------------- */
export function DmInbox() {
  const { user, nav } = useApp()
  const [refresh, setRefresh] = useState(0)
  const me = user?.pubkey
  const { ids, eose } = useSub(me ? [
    { kinds: [4], authors: [me], limit: 300 },
    { kinds: [4], '#p': [me], limit: 300 },
  ] : null, { enabled: !!me, ceil: 200 + refresh })
  const evs = useSortedEvents(ids)
  const convs = useMemo(() => {
    if (!me) return []
    const by = new Map()
    for (const ev of evs) {
      const other = ev.pubkey === me ? ev.tags.find((t) => t[0] === 'p')?.[1] : ev.pubkey
      if (!other) continue
      const prev = by.get(other)
      if (!prev || ev.created_at > prev.created_at) by.set(other, ev)
    }
    return [...by.entries()].sort((a, b) => b[1].created_at - a[1].created_at)
  }, [evs, me])

  if (!user) return (
    <div className="empty muted">
      Mensagens privadas criptografadas (NIP-04).
      <br /><br />
      <button className="btn primary" onClick={() => nav('/login')}>Conectar</button>
    </div>
  )
  return (
    <div className="dm-inbox">
      <div className="groups-head">
        <h2>✉️ Mensagens</h2>
        <button className="btn ghost tiny" onClick={() => setRefresh(refresh + 1)}>↻ Atualizar</button>
      </div>
      {convs.map(([pk, last]) => {
        const d = decryptText(last, me)
        return (
          <button key={pk} className="dm-row card" onClick={() => nav(`/dm/${nip19.npubEncode(pk)}`)}>
            <Avatar pk={pk} size={40} />
            <div className="dm-row-main">
              <div className="row"><strong>{nameOf(pk)}</strong><span className="tiny muted flex1 end">{timeAgo(last.created_at)}</span></div>
              <div className="tiny muted dm-preview">
                {last.pubkey === me ? 'você: ' : ''}{d.failed ? '[mensagem criptografada]' : (d.text || '').slice(0, 70)}
              </div>
            </div>
          </button>
        )
      })}
      {convs.length === 0 && (
        <div className="muted empty">
          {eose ? (
            <>
              Nenhuma conversa ainda. Abra o perfil de quem você segue e toque em "✉ DM" para começar.
              <br /><br />
              <button className="btn primary" onClick={() => nav('/')}>Explorar feed</button>
            </>
          ) : <LoadSpinner />}
        </div>
      )}
    </div>
  )
}

/* ---------------- conversation ---------------- */
export function DmThread({ npubOrHex }) {
  const { user, nav, api, toast } = useApp()
  const me = user?.pubkey
  let other = npubOrHex
  try { if (npubOrHex?.startsWith('npub')) other = nip19.decode(npubOrHex).data } catch {}
  const otherHex = other && other.length === 64 && /^[0-9a-fA-F]+$/.test(other) ? other : null

  const { ids } = useSub([
    { kinds: [4], authors: [me, otherHex].filter(Boolean), '#p': [me, otherHex].filter(Boolean), limit: 300 },
  ], { enabled: !!me && !!otherHex })
  const msgs = useSortedEvents(ids, { asc: true })
  const [text, setText] = useState('')
  const [busy, setBusy] = useState(false)
  const bottomRef = useRef(null)
  useEffect(() => { if (bottomRef.current?.scrollIntoView) bottomRef.current.scrollIntoView({ block: 'end' }) }, [ids.length])

  if (!user) return (
    <div className="empty muted">
      Conecte-se para trocar mensagens privadas.
      <br /><br />
      <button className="btn primary" onClick={() => nav('/login')}>Conectar</button>
    </div>
  )
  if (!otherHex || otherHex === me) return <p className="muted empty">Conversa inválida.</p>

  const send = async () => {
    const body = text.trim()
    if (!body || busy) return
    setBusy(true)
    try {
      const content = await encryptFor(otherHex, body)
      const ev = await api.signEvent({ kind: 4, content, tags: [['p', otherHex]] })
      const res = await api.publishEvent(ev)
      if (!res.ok.length) throw new Error('nenhum relay aceitou')
      toast('Mensagem enviada', 'ok')
      setText('')
    } catch (e) { toast('Falha ao enviar: ' + (e.message || e), 'error') }
    setBusy(false)
  }

  return (
    <div className="dm-page">
      <div className="dm-head card">
        <button className="btn back" onClick={() => nav('/dm')}>←</button>
        <Avatar pk={otherHex} size={34} />
        <strong>{nameOf(otherHex)}</strong>
        <span className="tiny muted">{shortNpub(otherHex, 8)}</span>
      </div>
      <div className="dm-msgs">
        {msgs.map((ev) => {
          const mine = ev.pubkey === me
          const d = decryptText(ev, me)
          return (
            <div key={ev.id} className={`dm-bubble-row ${mine ? 'mine' : ''}`}>
              <div className={`dm-bubble ${mine ? 'bubble-mine' : 'bubble-theirs'}`}>
                {d.failed && <span className="tiny">mensagem criptografada (sem app não-NIP-04)</span>}
                {!d.failed && <span className="prewrap">{d.text || ''}</span>}
                <div className="tiny muted">{mine ? '✓ ' : ''}{timeAgo(ev.created_at)}</div>
              </div>
            </div>
          )
        })}
        {msgs.length === 0 && <p className="muted empty">Nenhuma mensagem ainda — diga olá! 👋</p>}
      </div>
      <div className="dm-send card">
        <input
          value={text}
          placeholder="mensagem…"
          maxLength={1600}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send() } }}
        />
        <button className="btn primary" disabled={busy || !text.trim()} onClick={send}>{busy ? 'enviando…' : 'Enviar'}</button>
      </div>
      <div ref={bottomRef} />
    </div>
  )
}
