import { nip19 } from 'nostr-tools'

/** Collapse same-author repeated posts (same text) within a time window,
 *  keeping only the most recent copy of each streak. Input/output newest-first. */
export function dedupeRecent(evs, days = 45) {
  if (!evs?.length) return evs
  const key = (ev) => `${ev.pubkey}|${String(ev.content || '').trim().replace(/\s+/g, ' ').slice(0, 300)}`
  const lastKept = new Map() // key -> most recent KEPT event of that author+text
  const out = []
  for (const ev of evs) {
    const k = key(ev)
    const prev = lastKept.get(k)
    if (prev && prev.created_at - ev.created_at <= days * 86400) continue
    lastKept.set(k, ev)
    out.push(ev)
  }
  return out
}

export function timeAgo(sec) {
  const diff = Math.floor(Date.now() / 1000 - sec)
  if (diff < 45) return 'agora'
  const units = [
    ['a', 31536000], ['mês', 2592000], ['d', 86400], ['h', 3600], ['min', 60],
  ]
  const plurals = { a: 'a', 'mês': 'meses', d: 'd', h: 'h', min: 'min' }
  for (const [label, secs] of units) {
    if (diff >= secs * (label === 'min' ? 1 : 1)) {
      const n = Math.floor(diff / secs)
      if (label === 'a') return `${n} a`
      if (label === 'mês') return `${n} ${n === 1 ? 'mês' : 'meses'}`
      if (label === 'd') return `${n} d`
      if (label === 'h') return `${n} h`
      return `${n} min`
    }
  }
  return 'agora'
}

export function shortNpub(pk, n = 10) {
  try { return nip19.npubEncode(pk).slice(0, n) + '…' } catch { return pk?.slice(0, n) + '…' }
}

const HUES = {}
export function hueFor(pk) {
  if (!HUES[pk]) {
    let h = 0
    for (let i = 0; i < pk.length; i += 4) h = (h * 31 + parseInt(pk.slice(i, i + 4) || '0', 36)) % 360
    HUES[pk] = h
  }
  return HUES[pk]
}

export function displayName(meta, pk) {
  const name = meta?.display_name || meta?.name || meta?.displayName
  return name || shortNpub(pk)
}

export async function verifyNip05(nip05, pk) {
  if (!nip05) return false
  try {
    const [name, domain] = nip05.split('@')
    const url = `https://${domain}/.well-known/nostr.json?name=${encodeURIComponent(name === '_' ? '' : name)}`
    const res = await fetch(url, { signal: AbortSignal.timeout(5000) })
    if (!res.ok) return false
    const data = await res.json()
    const entry = data.names?.[name === '_' ? '' : name]
    return entry === pk || entry === nip19.npubEncode(pk) || false
  } catch { return false }
}

const CDN_ALLOWED = [
  'https://img.nostr.build', 'https://image.nostr.build', 'https://assets\.nostr\.build',
  'https://nostr.build', 'https://blossom.primal.net', 'https://nostrcheck.me',
  'https://cdn.satellite.earth', 'https://blossom.band', 'https://files\.nostr\.watch',
]

export function embedMediaUrl(url) {
  if (NOSTR_MEDIA_HOST.test(url)) return true
  return /\.(png|jpe?g|gif|webp|avif)(\?|#|$)/i.test(url)
}
export function embedVideoUrl(url) {
  return /\.(mp4|webm|mov)(\?|#|$)/i.test(url)
}
// Nostr file servers (Blossom / nostr.build / satellite) serve raw hashes without extension
const NOSTR_MEDIA_HOST = /^https?:\/\/[^/]*\b(?:blossom|image\.nostr\.build|nostr\.build|blob\.satellite\.earth|cdn\.satellite\.earth|cdn\.psi\.ce0\.e0\.fun)/i
