import React, { useMemo, useState } from 'react'
import { useApp } from './ctx'
import { PostCard } from './PostCard'
import { Composer } from './Composer'
import { useSub, useSortedEvents, useContacts } from '../lib/hooks'
import { dedupeRecent } from '../lib/util'
import { KINDS } from '../lib/nip22'

const PAGE_INITIAL = 30
const PAGE_STEP = 15

function FeedList({ evs, initial = PAGE_INITIAL, step = PAGE_STEP }) {
  const [n, setN] = useState(initial)
  const uniq = useMemo(() => dedupeRecent(evs), [evs])
  const shown = uniq.slice(0, n)
  return (
    <>
      {shown.map((ev) => <PostCard key={ev.id} event={ev} />)}
      {evs.length > shown.length && (
        <div className="loadmore-row">
          <button className="btn ghost full" onClick={() => setN(n + step)}>
            Carregar mais {step} ({shown.length} de {uniq.length})
          </button>
        </div>
      )}
      {uniq.length <= shown.length && uniq.length > initial && (
        <p className="tiny muted center">fim do feed — {uniq.length} posts</p>
      )}
    </>
  )
}

export function FeedPage() {
  const { route } = useApp()
  if (route.name === 'tag') return <TagFeed tag={route.params[0]} />
  return <MainFeed />
}

function Tab({ id, active, onClick, children }) {
  return <button className={`tabbtn ${active === id ? 'active' : ''}`} onClick={onClick}>{children}</button>
}

function MainFeed() {
  const [tab, setTab] = useState('home')
  return (
    <div className="feed-card card">
      <div className="tabs-row">
        <Tab id="home" active={tab} onClick={() => setTab('home')}>Início</Tab>
        <Tab id="following" active={tab} onClick={() => setTab('following')}>Seguindo</Tab>
        <Tab id="groups" active={tab} onClick={() => setTab('groups')}>Grupos</Tab>
      </div>
      {tab === 'home' && <GlobalFeed />}
      {tab === 'following' && <FollowingFeed />}
      {tab === 'groups' && <GroupsFeed />}
    </div>
  )
}

function GlobalFeed() {
  const { user } = useApp()
  const [rec, setRec] = useState(0)
  const since = useMemo(() => Math.floor(Date.now() / 1000) - 48 * 3600 - rec, [rec])
  const { ids } = useSub([{ kinds: [KINDS.POST, KINDS.COMMENT], since, limit: 400 }], { ceil: 300 })
  const evs = useSortedEvents(ids)
  const topLevel = (ev) => ev.kind === KINDS.POST || (ev.kind === KINDS.COMMENT && !ev.tags.some((t) => t[0] === 'e'))
  const [composerOpen, setComposerOpen] = useState(false)
  return (
    <>
      <div className="reload-row">
        <button className="btn ghost tiny" onClick={() => setRec(Date.now() % 100000)}>↻ Atualizar</button>
        {user && <button className="btn primary tiny" onClick={() => setComposerOpen(true)}>+ Novo post</button>}
      </div>
      {composerOpen && <div className="drawer"><Composer onClose={() => setComposerOpen(false)} /></div>}
      <FeedList evs={evs.filter(topLevel)} />
      {evs.filter(topLevel).length === 0 && <p className="muted empty">Carregando o feed público dos relays…</p>}
    </>
  )
}

function topLevelOf(ev) {
  return ev.kind === KINDS.POST || (ev.kind === KINDS.COMMENT && !ev.tags.some((t) => t[0] === 'e'))
}

function FollowingFeed() {
  const { user } = useApp()
  const contacts = useContacts(user?.pubkey)
  const authors = useMemo(() => {
    if (!user) return null
    const arr = [...(contacts || []), user.pubkey].filter(Boolean)
    return arr.length ? arr : []
  }, [contacts, user])
  const ready = !!authors && authors.length > 0 && !!contacts
  const { ids } = useSub(
    authors && authors.length ? [{ kinds: [KINDS.POST, KINDS.COMMENT], authors, limit: 500 }] : null,
    { enabled: ready, ceil: 300 }
  )
  const evs = useSortedEvents(ids)
  const list = evs.filter(topLevelOf)
  return (
    <>
      {!user && <p className="muted empty">Conecte-se (nsec / NIP-07) para ver quem você segue.</p>}
      {user && !contacts && <p className="muted empty">Carregando sua lista de contatos…</p>}
      {ready && <FeedList evs={list} />}
      {user && contacts && authors.length === 0 && (
        <p className="muted empty">Você ainda não segue ninguém. Explore grupos e perfis para seguir as pessoas.</p>
      )}
    </>
  )
}

function GroupsFeed() {
  const { joined, nav } = useApp()
  const enabled = joined.length > 0
  const { ids } = useSub(
    enabled ? [{ '#a': joined, kinds: [KINDS.COMMENT, KINDS.POST], limit: 600 }] : null,
    { enabled, ceil: 400 }
  )
  const evs = useSortedEvents(ids)
  const list = evs.filter(topLevelOf)
  return (
    <>
      {!enabled && (
        <div className="empty muted">
          Você ainda não participa de nenhum grupo.
          <br /><br />
          <button className="btn primary" onClick={() => nav('/groups')}>Explorar grupos</button>
        </div>
      )}
      {enabled && <FeedList evs={list} />}
    </>
  )
}

function TagFeed({ tag }) {
  const { ids } = useSub([{ kinds: [KINDS.POST, KINDS.COMMENT], '#t': [tag], limit: 400 }], { ceil: 300 })
  const evs = useSortedEvents(ids)
  return (
    <>
      <h3 className="section-title">#{tag}</h3>
      <FeedList evs={evs.filter(topLevelOf)} />
      {evs.length === 0 && <p className="muted empty">Buscando posts com #{tag}…</p>}
    </>
  )
}
